Use Supabase with React
import { createClient } from '@supabase/supabase-js' const supabase = createClient( process.env.SUPABASE_URL, process.env.SUPABASE_ANON_KEY ) export default function App() { const [todos, setTodos] = useState([]) useEffect(() => { supabase.from('todos').select('*') .then(({ data }) => setTodos(data)) }, []) return <TodoList items={todos} /> }
